      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Left ear hearing and blocked sensation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Decreased hearing on the left; feels blocked."
      }
    },
