      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Associated ear symptoms and possible exposures"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No ear discharge, tinnitus, vertigo, or upper respiratory tract symptoms. Possible mild night sweats, with no clear fevers. Using cotton buds; possible dirty water exposure."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Left ear examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Left external auditory canal mildly erythematous without oedema or debris. Tympanic membrane intact, slightly dull, and not bulging. No mastoid tenderness or lymphadenopathy."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Right ear examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Right ear NAD."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Left knee pain and functional symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Left knee pain for 5–6/7, now severe; increased pain with weight-bearing and stairs. Difficulty getting on and off the couch; almost fell. Unable to fully weight-bear. No trauma. Feels washed out and has poor sleep."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Left knee examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Obvious effusion; warm and erythematous compared with the right knee; very tender, especially medially and suprapatellarly. Markedly reduced range of motion, with flexion approximately 45° and almost no full extension. Passive movement painful. Unable to weight-bear without support."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Distal neurovascular status and other joints"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Distal neurovascularly intact. Other joints NAD."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Collateral history of mobility"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Wife reports the patient has been much less mobile this week and 'won't complain'."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Panadol"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "As needed"
          }
        ]
      }
    }
  ]
}
